import{_ as p,r as n,o,c as l,e as s,a as c,s as i}from"./chunks/framework.CXcwiNg-.js";const y=JSON.parse('{"title":"Макеты - October CMS - 3.x","titleTemplate":false,"description":"Определите каркас для страниц вашего сайта.","frontmatter":{"subtitle":"Определите каркас для страниц вашего сайта."},"headers":[{"level":2,"title":"Использование динамического заголовка страницы","slug":"использование-динамического-заголовка-страницы","link":"#использование-динамического-заголовка-страницы","children":[]},{"level":2,"title":"Заполнители","slug":"заполнители","link":"#заполнители","children":[]},{"level":2,"title":"Динамические макеты","slug":"динамические-макеты","link":"#динамические-макеты","children":[{"level":3,"title":"Жизненный цикл выполнения макета","slug":"жизненныи-цикл-выполнения-макета","link":"#жизненныи-цикл-выполнения-макета","children":[]},{"level":3,"title":"Доступ к методам и переменным","slug":"доступ-к-методам-и-переменным","link":"#доступ-к-методам-и-переменным","children":[]},{"level":3,"title":"Приоритетные макеты","slug":"приоритетные-макеты","link":"#приоритетные-макеты","children":[{"level":4,"title":"Смотрите также","slug":"смотрите-также","link":"#смотрите-также","children":[]}]}]}],"relativePath":"3.x/ru/cms/themes/layouts.md","filePath":"3.x/ru/cms/themes/layouts.md"}'),u={name:"3.x/ru/cms/themes/layouts.md"};function g(k,a,d,r,m,h){const t=n("pre-heading"),e=n("post-heading");return o(),l("div",null,[s(t),a[0]||(a[0]=c("h1",null,"Макеты",-1)),s(e),a[1]||(a[1]=i(`<p>Макеты определяют общий каркас для ваших страниц, который обычно включает всё, что повторяется на каждой странице, например, шапку и подвал. Они почти всегда содержат HTML-код, такой как теги HEAD, TITLE и BODY.</p><p>Файлы шаблонов макетов располагаются в каталоге <strong>layouts</strong> вашей темы. Файлы шаблонов макетов должны иметь расширение <strong>htm</strong>. Внутри файла макета следует использовать тег <code>{% page %}</code> для вывода содержимого страницы. Далее приведён пример простейшего макета.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>html</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>body</span><span class="token punctuation">&gt;</span></span>
        <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">page</span> <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>body</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>html</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><div class="custom-block aside"><p>Помните, что при обращении к макету из подкаталога необходимо указывать имя подкаталога.</p></div><p>Чтобы использовать макет для <a href="./pages.html">страницы</a>, страница должна ссылаться на имя файла макета (без расширения) в секции конфигурации. Ниже приведён пример шаблона страницы, использующего макет <strong>default.htm</strong>.</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/</span>&quot;</span>
<span class="token key attr-name">layout</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">default</span>&quot;</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>Hello, world!<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
</code></pre></div></div><p>При запросе этой страницы её содержимое объединяется с макетом, а точнее — тег <code>{% page %}</code> макета заменяется содержимым страницы. Предыдущие примеры сгенерируют следующую разметку:</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>html</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>body</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>Hello, world!<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>body</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>html</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>Обратите внимание, что вы можете <a href="./partials.html">рендерить фрагменты</a> в макетах. Это позволяет использовать общие элементы разметки в разных макетах. Например, вы можете создать фрагмент, который выводит ссылки на CSS и JavaScript файлы сайта. Такой подход упрощает управление ресурсами — если вам нужно добавить ссылку на JavaScript, достаточно изменить один фрагмент вместо редактирования всех макетов.</p><p>Секция конфигурации является необязательной для макетов. Поддерживаемые параметры конфигурации: <strong>name</strong> и <strong>description</strong>. Эти параметры необязательны и используются в интерфейсе администрирования. Пример шаблона макета с описанием:</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">description</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Basic layout example</span>&quot;</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>html</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>body</span><span class="token punctuation">&gt;</span></span>
        <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">page</span> <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>body</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>html</span><span class="token punctuation">&gt;</span></span>
</code></pre></div></div><h2 id="использование-динамического-заголовка-страницы"><a href="#использование-динамического-заголовка-страницы" class="header-anchor">#</a> Использование динамического заголовка страницы</h2><p>Свойства <code>meta_title</code> и <code>meta_description</code> <a href="./pages.html">страницы</a> поддерживают парсинг переменных из жизненного цикла страницы. Следующий шаблон макета установит заголовок страницы на основе значения активной страницы.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>html</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>head</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>title</span><span class="token punctuation">&gt;</span></span>{{ this.page.meta_title }} - October CMS<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>title</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>head</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>body</span><span class="token punctuation">&gt;</span></span>
        {% page %}
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>body</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>html</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>Шаблон страницы может затем определить свой заголовок, используя Twig-подобный синтаксис переменных с использованием значений, доступных в глобальном окружении — в данном случае используется значение <strong>post.title</strong>.</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/blog</span>&quot;</span>
<span class="token key attr-name">meta_title</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">{{ post.title }} - Blog</span>&quot;</span>
</code></pre></div><blockquote><p><strong>Примечание</strong>: Поддерживаются только базовые переменные Twig. Фильтры, теги и функции использовать нельзя.</p></blockquote><h2 id="заполнители"><a href="#заполнители" class="header-anchor">#</a> Заполнители</h2><p>Заполнители позволяют страницам внедрять содержимое в макет. Заполнители определяются в шаблонах макетов с помощью тега <code>{% placeholder %}</code>. Следующий пример показывает шаблон макета с заполнителем <strong>head</strong>, определённым в секции HTML HEAD.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>html</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>head</span><span class="token punctuation">&gt;</span></span>
        <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">placeholder</span> head <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>head</span><span class="token punctuation">&gt;</span></span>
    ...
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>html</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>Страницы могут внедрять содержимое в заполнители с помощью тегов <code>{% put %}</code> и <code>{% endput %}</code>. Следующий пример демонстрирует простой шаблон страницы, который внедряет ссылку на CSS в заполнитель <strong>head</strong>, определённый в предыдущем примере.</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/my-page</span>&quot;</span>
<span class="token key attr-name">layout</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">default</span>&quot;</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">put</span> head <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>link</span> <span class="token attr-name">href</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>/themes/demo/assets/css/page.css<span class="token punctuation">&quot;</span></span> <span class="token attr-name">rel</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>stylesheet<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endput</span> <span class="token delimiter punctuation">%}</span></span>

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>The page content goes here.<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
</code></pre></div></div><p>Более подробную информацию о заполнителях можно найти <a href="./../markup/tag-placeholder.html">в руководстве по разметке</a>.</p><h2 id="динамические-макеты"><a href="#динамические-макеты" class="header-anchor">#</a> Динамические макеты</h2><p>Макеты, как и страницы, могут использовать любые возможности Twig. Подробнее см. раздел <a href="./pages.html">Динамические страницы</a> документации.</p><h3 id="жизненныи-цикл-выполнения-макета"><a href="#жизненныи-цикл-выполнения-макета" class="header-anchor">#</a> Жизненный цикл выполнения макета</h3><p>В секции PHP макета вы можете определить следующие функции для обработки жизненного цикла выполнения страницы: <code>onInit</code>, <code>onStart</code>, <code>onBeforePageStart</code> и <code>onEnd</code>.</p><p>Функция <code>onInit</code> выполняется, когда все компоненты инициализированы и до обработки AJAX-запросов. Функция <code>onStart</code> выполняется в начале обработки страницы. Функция <code>onBeforePageStart</code> выполняется после выполнения <a href="./components.html">компонентов</a> макета, но до выполнения функции <code>onStart</code> страницы. Функция <code>onEnd</code> выполняется после рендеринга страницы. Последовательность выполнения обработчиков следующая:</p><ol><li>Layout <code>onInit()</code> function.</li><li>Page <code>onInit()</code> function.</li><li>Layout <code>onStart()</code> function.</li><li>Layout components <code>onRun()</code> method.</li><li>Layout <code>onBeforePageStart()</code> function.</li><li>Page <code>onStart()</code> function.</li><li>Page components <code>onRun()</code> method.</li><li>Page <code>onEnd()</code> function.</li><li>Layout <code>onEnd()</code> function.</li></ol><h3 id="доступ-к-методам-и-переменным"><a href="#доступ-к-методам-и-переменным" class="header-anchor">#</a> Доступ к методам и переменным</h3><p>При доступе к переменным и методам внутри фрагментов, страниц и макетов используется ближайший контекст. Возьмём следующее определение <a href="./themes.html">секции PHP-кода</a>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onStart</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;myVariable&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;foo&#39;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>

<span class="token keyword">function</span> <span class="token function-definition function">myMethod</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token string single-quoted-string">&#39;bar&#39;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>В приведённом выше примере при обращении к <code>myVariable</code> или <code>this.myMethod()</code> внутри Twig проверка существования выполняется в следующем порядке:</p><ol><li>Фрагмент</li><li>Страница</li><li>Макет</li></ol><h3 id="приоритетные-макеты"><a href="#приоритетные-макеты" class="header-anchor">#</a> Приоритетные макеты</h3><p>Макеты могут указывать атрибут <code>is_priority</code> в своих настройках для активации приоритетного режима. В обычных условиях содержимое макета рендерится после содержимого страницы. Это позволяет странице управлять свойствами макета, такими как заголовок или мета-описание. Визуально порядок выглядит так.</p><div class="language-text extra-class"><pre class="language-text"><code>Layout (3) ← Page (1) → Partials (2)
</code></pre></div><p>В приоритетном режиме макет использует более естественный порядок загрузки, при котором тег <code>{% page %}</code> рендерится в одной последовательности с содержимым макета. Однако при использовании этого режима заполнители не поддерживаются. Порядок загрузки приоритетного макета выглядит примерно так.</p><div class="language-text extra-class"><pre class="language-text"><code>Layout (1) → Page (2) → Partials (3)
</code></pre></div><p>Это особенно полезно при <a href="./../resources/building-apis.html">создании API-эндпоинтов</a>. В следующем примере логика страницы не будет выполнена, поскольку тег page никогда не вызывается.</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">description</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">API Layout</span>&quot;</span>
<span class="token key attr-name">is_priority</span> <span class="token punctuation">=</span> <span class="token value attr-value">1</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">if</span> <span class="token boolean">false</span> <span class="token delimiter punctuation">%}</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">page</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endif</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div></div><h4 id="смотрите-также"><a href="#смотрите-также" class="header-anchor">#</a> Смотрите также</h4><div class="custom-block also"><ul><li><a href="./../../markup/tag/page.html">Page Twig Tag</a></li></ul></div>`,43))])}const f=p(u,[["render",g]]);export{y as __pageData,f as default};
